<?php
require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requireLogin();$db=Database::connect();marketplace_install($db);$pageTitle='Flash Sale';$err='';
if(is_post()){if(!CSRF::verify())$err='Token keamanan tidak valid.';else try{$a=$_POST['action']??'sale_save';if($a==='sale_save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$start=trim((string)($_POST['starts_at']??''));$end=trim((string)($_POST['ends_at']??''));if($name===''||!$start||!$end)throw new InvalidArgumentException('Nama dan periode wajib diisi.');if(strtotime($end)<=strtotime($start))throw new InvalidArgumentException('Tanggal selesai harus setelah mulai.');$active=isset($_POST['is_active'])?1:0;if($id)$db->prepare("UPDATE marketplace_flash_sales SET name=?,starts_at=?,ends_at=?,is_active=?,updated_at=NOW() WHERE id=?")->execute([$name,$start,$end,$active,$id]);else{$db->prepare("INSERT INTO marketplace_flash_sales(name,starts_at,ends_at,is_active,created_at) VALUES(?,?,?,?,NOW())")->execute([$name,$start,$end,$active]);$id=(int)$db->lastInsertId();}marketplace_v15_log($db,'flash_sale.save','flash_sale',$id,$name);flash('success','Flash sale disimpan.');legacy_redirect('admin/marketplace-flash-sales/index.php?edit='.$id);}
if($a==='sale_delete'){$id=(int)$_POST['id'];$db->prepare("DELETE FROM marketplace_flash_sale_items WHERE flash_sale_id=?")->execute([$id]);$db->prepare("DELETE FROM marketplace_flash_sales WHERE id=?")->execute([$id]);flash('success','Flash sale dihapus.');legacy_redirect('admin/marketplace-flash-sales/index.php');}
if($a==='item_add'){$sale=(int)$_POST['sale_id'];$pid=(int)$_POST['product_id'];$vid=max(0,(int)($_POST['variant_id']??0));$price=max(0,(float)$_POST['sale_price']);$limit=max(0,(int)($_POST['stock_limit']??0));if(!$sale||!$pid||$price<=0)throw new InvalidArgumentException('Produk dan harga flash sale wajib.');if($vid>0){$chk=$db->prepare("SELECT product_id FROM marketplace_product_variants WHERE id=? AND product_id=? AND is_active=1");$chk->execute([$vid,$pid]);if(!$chk->fetchColumn())throw new InvalidArgumentException('Varian tidak cocok dengan produk yang dipilih.');$db->prepare("INSERT INTO marketplace_flash_sale_items(flash_sale_id,product_id,variant_id,sale_price,stock_limit,sold_count,created_at) VALUES(?,?,?,?,?,0,NOW()) ON DUPLICATE KEY UPDATE sale_price=VALUES(sale_price),stock_limit=VALUES(stock_limit)")->execute([$sale,$pid,$vid,$price,$limit]);}else{$existing=$db->prepare("SELECT id FROM marketplace_flash_sale_items WHERE flash_sale_id=? AND product_id=? AND variant_id IS NULL LIMIT 1");$existing->execute([$sale,$pid]);$iid=(int)$existing->fetchColumn();if($iid)$db->prepare("UPDATE marketplace_flash_sale_items SET sale_price=?,stock_limit=? WHERE id=?")->execute([$price,$limit,$iid]);else $db->prepare("INSERT INTO marketplace_flash_sale_items(flash_sale_id,product_id,variant_id,sale_price,stock_limit,sold_count,created_at) VALUES(?,?,NULL,?,?,0,NOW())")->execute([$sale,$pid,$price,$limit]);}flash('success','Produk flash sale ditambahkan.');legacy_redirect('admin/marketplace-flash-sales/index.php?edit='.$sale);}
if($a==='item_delete'){$iid=(int)$_POST['item_id'];$sale=(int)$_POST['sale_id'];$db->prepare("DELETE FROM marketplace_flash_sale_items WHERE id=? AND flash_sale_id=?")->execute([$iid,$sale]);flash('success','Item flash sale dihapus.');legacy_redirect('admin/marketplace-flash-sales/index.php?edit='.$sale);}}
catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$db->prepare("SELECT * FROM marketplace_flash_sales WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$sales=$db->query("SELECT f.*,(SELECT COUNT(*) FROM marketplace_flash_sale_items i WHERE i.flash_sale_id=f.id) item_count FROM marketplace_flash_sales f ORDER BY f.id DESC")->fetchAll()?:[];$items=[];if($edit){$s=$db->prepare("SELECT i.*,p.name product_name,v.name variant_name FROM marketplace_flash_sale_items i JOIN products p ON p.id=i.product_id LEFT JOIN marketplace_product_variants v ON v.id=i.variant_id WHERE i.flash_sale_id=? ORDER BY i.id DESC");$s->execute([$edit['id']]);$items=$s->fetchAll()?:[];}$products=$db->query("SELECT id,name,selling_price FROM products WHERE is_active=1 ORDER BY name ASC LIMIT 1000")->fetchAll()?:[];$variantRows=$db->query("SELECT id,product_id,name,selling_price FROM marketplace_product_variants WHERE is_active=1 ORDER BY product_id,sort_order,id")->fetchAll()?:[];$ok=flash('success');require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Flash Sale</h1><p>Harga promo terbatas dengan periode otomatis.</p></div></header><?php if($ok):?><div class="mp-alert success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="mp-alert error"><?=e($err)?></div><?php endif;?><section class="mp-admin-grid two"><section class="mp-panel"><div class="mp-panel-head"><h3><?=$edit?'Edit Flash Sale':'Flash Sale Baru'?></h3></div><form method="post" class="mp-form"><?=CSRF::input()?><input type="hidden" name="action" value="sale_save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Nama<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Mulai<input type="datetime-local" name="starts_at" required value="<?=!empty($edit['starts_at'])?e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):''?>"></label><label>Selesai<input type="datetime-local" name="ends_at" required value="<?=!empty($edit['ends_at'])?e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):''?>"></label><label class="mp-check"><input type="checkbox" name="is_active" <?=$edit&&!$edit['is_active']?'':'checked'?>> Aktif</label><button class="mp-btn">Simpan Flash Sale</button></form><?php if($edit):?><hr><form method="post" class="mp-form"><?=CSRF::input()?><input type="hidden" name="action" value="item_add"><input type="hidden" name="sale_id" value="<?=$edit['id']?>"><label>Produk<select name="product_id" id="flashProduct" required><option value="">Pilih produk</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> — <?=rupiah($p['selling_price'])?></option><?php endforeach;?></select></label><label>Varian<select name="variant_id" id="flashVariant"><option value="0">Produk utama</option></select><small>Daftar varian mengikuti produk yang dipilih.</small></label><label>Harga Flash<input type="number" name="sale_price" min="1" required></label><label>Limit Qty <small>(0 = ikut stok)</small><input type="number" name="stock_limit" min="0" value="0"></label><button class="mp-btn"><i class="bi bi-plus"></i> Tambah Item</button></form><?php endif;?></section><section class="mp-panel"><div class="mp-panel-head"><h3>Daftar Flash Sale</h3></div><div class="table-premium-card"><table class="premium-table"><thead><tr><th>Nama</th><th>Periode</th><th>Item</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($sales as $f):?><tr><td><b><?=e($f['name'])?></b></td><td><small><?=e(date('d/m/Y H:i',strtotime($f['starts_at'])))?><br><?=e(date('d/m/Y H:i',strtotime($f['ends_at'])))?></small></td><td><?=e($f['item_count'])?></td><td><?=$f['is_active']?'Aktif':'Off'?></td><td><a class="mp-icon" href="?edit=<?=$f['id']?>"><i class="bi bi-pencil"></i></a><form method="post" style="display:inline" onsubmit="return confirm('Hapus flash sale?')"><?=CSRF::input()?><input type="hidden" name="action" value="sale_delete"><input type="hidden" name="id" value="<?=$f['id']?>"><button class="mp-icon danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div><?php if($edit):?><div class="table-premium-card"><table class="premium-table"><thead><tr><th>Produk</th><th>Harga Flash</th><th>Limit</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?=e($i['product_name'])?></b><br><small><?=e($i['variant_name']?:'Produk utama')?></small></td><td><?=rupiah($i['sale_price'])?></td><td><?=e($i['stock_limit']?:'Ikut stok')?></td><td><form method="post"><?=CSRF::input()?><input type="hidden" name="action" value="item_delete"><input type="hidden" name="sale_id" value="<?=$edit['id']?>"><input type="hidden" name="item_id" value="<?=$i['id']?>"><button class="mp-icon danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></section></main><script>(()=>{const product=document.getElementById('flashProduct'),variant=document.getElementById('flashVariant');if(!product||!variant)return;const rows=<?=json_encode($variantRows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const refresh=()=>{const pid=Number(product.value||0);variant.innerHTML='<option value="0">Produk utama</option>'+rows.filter(r=>Number(r.product_id)===pid).map(r=>'<option value="'+Number(r.id)+'">'+esc(r.name)+' — '+new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(r.selling_price||0))+'</option>').join('');};product.addEventListener('change',refresh);refresh();})();</script><?php require __DIR__.'/../../layouts/admin-footer.php';?>
